package com.asmj.marketplace.event.service;
import com.asmj.marketplace.event.model.EventListing;import com.asmj.marketplace.event.repository.EventListingRepository;import com.asmj.marketplace.user.repository.UserRepository;import com.asmj.marketplace.vendor.repository.VendorRepository;import lombok.RequiredArgsConstructor;import org.springframework.beans.factory.annotation.Value;import org.springframework.boot.CommandLineRunner;import org.springframework.stereotype.Component;import java.time.*;import java.util.*;
@Component @RequiredArgsConstructor public class EventDataSeeder implements CommandLineRunner { final EventListingRepository events;final UserRepository users;final VendorRepository vendors;@Value("${app.seed.enabled:true}") boolean enabled;public void run(String... args){if(!enabled||events.count()>0)return;var v=users.findByEmailIgnoreCase("demo.learning@asmj.co.in").flatMap(u->vendors.findByUserId(u.getId())).orElse(null);if(v==null)return;Instant n=Instant.now();LocalDate d=LocalDate.now().plusDays(14);events.save(EventListing.builder().vendorId(v.getId()).organizerName(v.getBusinessName()).name("Spring Boot Production Workshop").category("Workshop").description("Hands-on Spring Boot, MongoDB and deployment workshop for developers.").eventDate(d).startTime(LocalTime.of(10,0)).endTime(LocalTime.of(14,0)).venue("ASMJ Learning Centre").address("Indiranagar, Bengaluru").city("Bengaluru").capacity(100).availableSeats(100).ticketPrice(999).registrationDeadline(d.minusDays(1).atTime(23,59)).images(new ArrayList<>()).terms("Tickets are subject to event terms and organizer policy.").status("PUBLISHED").approved(true).active(true).views(0).createdAt(n).updatedAt(n).build());}}
